import pandas as pd

def count_tasks(tasks: pd.DataFrame) -> pd.DataFrame:
    if tasks.empty:
        return pd.DataFrame([{'weekend_cnt': 0, 'working_cnt': 0}])
    dates = pd.to_datetime(tasks['assign_date'])
    is_weekend = dates.dt.dayofweek >= 5
    return pd.DataFrame([{
        'weekend_cnt': int(is_weekend.sum()),
        'working_cnt': int((~is_weekend).sum())
    }])
